import fs from 'node:fs';

// E23 is refined in independent, reviewable waves. Never synthesize a policy
// threshold here: the initial values below come from the existing E23 epic.
const epic = JSON.parse(fs.readFileSync(new URL('../docs/jira/v1.3/epics/e23.json', import.meta.url), 'utf8'));
const byId = new Map(epic.issues.map(issue => [issue.sourceId, issue]));
const target = new URL('../docs/jira/v1.3/refinements/e23.json', import.meta.url);
const existing = fs.existsSync(target) ? JSON.parse(fs.readFileSync(target, 'utf8')) : { refinements: [], additions: [] };
const overrides = new Map(existing.refinements.map(issue => [issue.sourceId, issue]));

function parent(id, outcome, context) {
  overrides.set(id, { sourceId: id, outcome, context, specStatus: 'refined-parent', dispatchable: false });
}

function leaf(story, index, { title, outcome, context, scope, excluded, owner, interfaces, states, actions, groups, conditions, tests, deps = [], labels = [] }) {
  const id = `VS-E23-${story}-ST${String(index).padStart(2, '0')}`;
  const original = byId.get(id);
  if (!original) throw Error(`Missing source ${id}`);
  const repository = original.repositories[0];
  const ac = conditions.map(([given, when, then], n) => ({ id: `AC0${n + 1}`, given, when, then }));
  overrides.set(id, {
    sourceId: id, summary: `[${id}] ${title}`, actor: repository.startsWith('frontend_') ? 'Authorized customer or backoffice operator' : 'Authorized internal producer, reviewer or implementation engineer',
    outcome, context, inScope: scope, outOfScope: excluded,
    repositories: [repository], primaryRepository: repository,
    repositorySlices: [{ repository, paths: owner.paths, artifacts: owner.artifacts }],
    interfaces, dataOwnership: owner.boundaries, stateMachine: states,
    authorization: {
      actions,
      dataPartitions: ['CUSTOMER only for its own subject; ADMIN only with the authorized organization/site/branch and target-customer relationship; SYSTEM only for authenticated, purpose-bound service calls.'],
      fieldGroups: groups,
    },
    failureSemantics: ['Reject missing grants and unknown subjects without disclosing existence or protected source facts.', 'Absent or stale source/identity/policy version must return explicit unavailable or unassessed state; never infer a positive trust outcome.', 'Do not log PII, detailed financial history, raw cleanliness notes, or signed URLs.'],
    idempotencyConcurrency: ['Deduplicate ingested events by owner, event ID, source revision and customer; repeated delivery cannot create new facts.', 'Externally retried writes use scoped idempotency key, request fingerprint and expected revision; concurrent conflicts expose a stable code.', 'Historical facts and decisions are append-only; correction publishes a linked compensating fact rather than overwriting the source.'],
    dependencies: deps.map(sourceId => ({ sourceId, relation: 'is-blocked-by' })),
    acceptanceCriteria: ac,
    tests: ['Run the exact commands in testCases; add positive, cross-customer denial, unavailable-source, duplicate/reorder and compensation cases appropriate to this slice.', 'Attach machine-readable CI evidence and source-to-AC mapping; no simulated production approval or live secret is allowed.'],
    testCases: tests.map((command, n) => ({ id: `TEST-0${n + 1}`, level: n === 0 ? 'unit' : 'integration', command, verifies: n === 0 ? ['AC01', 'AC02'] : ['AC01', 'AC02', 'AC03'], evidence: `${id} focused CI output, denial/replay assertions and fixture version` })),
    observability: ['Propagate correlation and source event IDs across the named boundary; record bounded result/replay/stale-source counters without customer PII.', 'Expose the source version, last successfully consumed watermark and recoverable failure reason to authorized operators.'],
    definitionOfDone: ['Named artifacts are committed in the owning repository; focused tests and CI pass.', 'Contract owner approves field/action partition matrix and retry/compensation behavior.', 'Jira has PR, tests, denial/replay evidence, and rollback/repair instructions; this task does not claim the runtime feature already exists.'],
    evidence: ['PR and CI URL for the owning repository.', 'Unit/integration result with positive, denial and replay/reordering fixture.', 'Contract compatibility and migration/rollback note where applicable.'],
    labels: [...new Set([...original.labels, ...labels])],
    decisionNoteVi: `Only ${repository} owns this slice. Finance alone owns the canonical customer trust facts, policy, score and waiver decision; no new policy values are approved by this spec.`,
    specStatus: 'executable', workKind: repository.startsWith('frontend_') ? 'web' : repository === 'platform_contracts' ? 'contract' : 'service',
    dispatchable: true, decisions: [], implementationBlockers: [], activationBlockers: [], externalBlockers: [],
  });
}

const gradle = ['.\\gradlew.bat test --tests "*Trust*"', '.\\gradlew.bat test'];
const admin = ['npm run typecheck', 'npm test'];
// Customer currently has no test script; implementation must add one rather
// than treating a successful typecheck/build as proof of API security cases.
const customer = ['npm run build', 'npm run lint && npm test'];
const contracts = ['npm run validate:schemas', 'npm test'];
const owner = (repo, artifacts, boundaries) => ({ paths: repo === 'frontend_admin' ? ['apps/web/src/**', 'apps/mobile/src/**'] : repo === 'frontend_customer' ? ['src/**'] : repo === 'platform_contracts' ? ['schemas/customer-trust/**', 'graphql/backoffice/**', 'fixtures/customer-trust/**'] : ['src/main/java/**', 'src/main/resources/**', 'src/test/java/**'], artifacts, boundaries });
const C = (...conditions) => conditions;

parent('VS-E23', 'Finance owns the versioned trust ledger, scoring policy, profile, waiver decision and appeals; six stories separate immutable source facts, policy, projection, deposit, appeals and scoped investigation.', 'This is delivery planning, not a claim that trust tables, endpoints or weights have been implemented. The epic baseline proposes initial score weights/thresholds subject to effective-dated policy approval; every downstream source retains its own authority.');
parent('VS-E23-S01', 'S01 normalizes payment, booking, cleanliness and identity source evidence into an append-only Finance trust fact ledger, with read-only UI provenance and versioned contracts.', 'Cleaning scores must be supplied by the external employee system through Operations, and stayover vs checkout cleanliness remain distinguishable. No customer or Admin browser may author trust facts.');
parent('VS-E23-S02', 'S02 gives Finance the only policy writer, effective dating, simulation and maker-checker publication, with consumer validation and restricted Admin review screens.', 'The existing E23 policy numbers are an initial configurable proposal, not evidence of an active production policy. Publishing requires approved version and fixtures; Consumers do not publish or score independently.');

leaf('S01', 1, { title:'Ingest append-only customer trust facts in Finance', outcome:'Finance stores immutable customer-scoped facts from authenticated source owners without calculating a second source ledger in User or Booking.', context:'E23 assigns normalized trust-fact ownership to Finance. Payment reversals and overdue obligations originate in Finance; Booking supplies completed stays/no-shows, Operations supplies signed cleanliness assessments, User supplies verified identity.', scope:['Define durable source-event inbox and canonical fact identity (source owner, event ID, revision, responsible customer, category, occurredAt, evidence reference).','Normalize payment/booking/cleanliness/conduct facts with stayover versus checkout evidence explicitly separated; record pending dispute without final point deduction.','Append compensating correction referencing the original fact; retain a source watermark, hard-blocker provenance, reprocessing and non-destructive migration.'], excluded:['Direct reads of Booking/Operations/User tables.', 'Inventing cleanliness evidence or adjusting published policy/score as part of ingestion.'], owner:owner('service_finance',['trust-fact/inbox persistence and outbox','normalizer, source adapter and migration','duplicate/reorder/compensation integration tests'],['Finance owns normalized immutable facts; each producer retains raw evidence and must authorize dereference.']), interfaces:['Consume versioned producer events through authenticated inbox with explicit schema version, subject ID, source revision and source evidence ID.','Reject unknown/mismatched customer identities and source owners with stable codes; report lag and rejected events.'], states:['RECEIVED -> VALIDATED -> APPLIED or QUARANTINED; retries never rewrite an APPLIED fact.','A correction produces a new LINKED_REVERSAL fact; a disputed negative fact is flagged pending and blocks automatic waiver until resolved.'], actions:['trust:fact:ingest','trust:fact:read-provenance'],groups:['SUMMARY excludes raw source evidence; TRUST_DETAIL and FINANCIAL require separate grants; INTERNAL_AUDIT controls source payload/replay.'], conditions:C(['authenticated payment, completed-booking and two different cleaning events for one responsible customer','the inbox processes each event','Finance stores four uniquely sourced facts, distinct stayover/checkout categories and one committed outbox transition per fact'],['wrong producer, absent customer or cross-customer evidence reference','normalization runs','input is quarantined without creating an eligible profile or exposing source payload'],['same event is retried or an earlier revision/correction arrives out of order','replay runs','only the valid append-only revision graph survives and the original source fact remains immutable']),tests:gradle,deps:['VS-E23-S01-ST07','VS-E09-T08','VS-E12-S07'] });

leaf('S01', 2, { title:'Publish separately signed stayover and checkout care evidence', outcome:'Operations exports authorized, revisioned guest-care evidence to Finance without assuming raw cleaning notes equal guest fault.', context:'E12-S07 supplies external employee-system assessments; missing or unauthenticated external input is not evidence. Housekeeping stayover and checkout are distinct kinds with separately configurable points in Finance policy.',scope:['Map external employee-system stayover/checkout assessment to booking, responsible customer, assessor identity, evidence type and event revision.','Expose a reviewable correction/refutation for erroneous cleaning evidence and emit an outbox event; suppress cleaning-staff operational notes not attributable to the guest.','Emit no event when assessment source is unauthenticated or booking/customer ownership cannot be proven.'],excluded:['Calculating scores or copying Finance policy into Operations.','Treating the presence of a dirty room as verified guest misconduct without assessor provenance.'],owner:owner('service_operations',['stayover/checkout assessment outbound event','assessment attribution and correction tests'],['Operations owns raw assessment and source attribution; Finance owns trust category and score.']),interfaces:['Version and publish guest-care fact/correction events from the authorized Operations assessment with source event ID and signed origin.'],states:['EVIDENCE_ACCEPTED -> PUBLISHED or CORRECTED_BY_LINKED_EVENT; rejected external payload is not published.'],actions:['operations:care-evidence:publish'],groups:['SUMMARY only for event status; TRUST_DETAIL/DOCUMENT for assessment provenance; raw notes stay restricted.'],conditions:C(['two verified assessments, one stayover and one checkout, attributable to the same booking','Operations publishes events','the two types, evidence references and revisions are distinct and Finance can consume them'],['external assessor unsigned, booking mismatch or guest attribution uncertain','event mapping runs','no trust event is emitted and a repairable reason is recorded'],['assessment is amended and same outbox event is redelivered','Finance consumes it','only one linked correction is applied and the first assessment stays auditable']),tests:gradle,deps:['VS-E12-S07','VS-E23-S01-ST07'] });

leaf('S01', 3, { title:'Publish completed-stay cancellation and no-show trust evidence', outcome:'Booking publishes responsible-customer booking events for Finance trust normalization while retaining booking-state authority.',context:'Staff creator is not the trust subject. A confirmed booking does not imply a completed stay; no-show and cancellation are distinct and may be disputed.',scope:['Emit stable completed-stay and no-show events with booking ID, responsible customer ID, stay end and source revision.','Emit cancellation/adjustment and subsequent correction events with unambiguous linked IDs and event ordering.','Reject events without a responsible customer association; keep employee creator as provenance only.'],excluded:['Mutating Finance score or converting a booking quote into a trust fact.'],owner:owner('service_booking',['outbox booking trust events','responsible-customer attribution fixture','cancel/no-show/replay tests'],['Booking owns booking state and booking/customer attribution; Finance owns interpreted trust facts.']),interfaces:['Version Booking completed/cancelled/no-show and linked correction events; use transactional outbox and stable booking revision.'],states:['Only authoritative booking transition emits a fact; corrected source state emits a linked new event rather than changing the original.'],actions:['booking:trust-evidence:publish'],groups:['SUMMARY includes booking reference; INTERNAL_AUDIT alone includes source revision/history.'],conditions:C(['a staff-created booking assigned to a customer is completed','booking outbox publishes','the customer, not the employee, is the trust subject and a completed-stay fact is available'],['no responsible customer, or cancelled booking represented as completed','producer attempts publication','no completed-stay trust event is emitted'],['a no-show is disputed or event is redelivered after correction','source replays events','Finance can distinguish original, dispute and linked correction without double-counting']),tests:gradle,deps:['VS-E23-S01-ST07'] });

leaf('S01', 4, { title:'Expose verified customer identity and account linkage as trust gate',outcome:'User supplies versioned customer identity/verified-email and account-linkage assertions, never its own score.',context:'Unassessed customers and staff-created bookings must not be assigned a staff trust profile; verified identity/history affects confidence and eligibility, not score points.',scope:['Publish verified-email status, customer account subject and revocation/merge change with trusted identity source revision.','Ensure only a customer account can be associated with a trust subject; propagate revocations as linked events.','Provide authorized purpose-bound identity lookup for Finance without exposing Keycloak credentials or cross-customer PII.'],excluded:['Creating trust tables or assigning Finance tier/waiver in User.'],owner:owner('service_user',['identity assertion versioned event/lookup','customer-vs-employee and verification-revocation tests'],['User owns account linkage and verified identity, Keycloak owns authentication; Finance owns trust profile.']),interfaces:['Purpose-scoped customer identity assertion and verification-change event consumed by Finance with source revision.'],states:['UNVERIFIED -> VERIFIED -> REVOKED as new revisioned assertions; no hard-delete of identity provenance.'],actions:['user:identity:trust-assert'],groups:['SUMMARY signals verified flag only; PII and INTERNAL_AUDIT are restricted and not shipped in trust events.'],conditions:C(['verified customer email and a staff-created booking linked to that customer','Finance requests identity assertion','customer identity and verification revision are returned, with no employee score created'],['employee subject, unknown customer or missing service grant','lookup is attempted','request fails closed without any cross-account email or trust disclosure'],['verification is revoked or accounts are corrected','identity event is replayed','Finance sees a newer revision and invalidates stale eligibility without replacing historical assertions']),tests:gradle,deps:['VS-E23-S01-ST07'] });

leaf('S01', 5, { title:'Show restricted trust source provenance in Admin Web and Mobile',outcome:'An authorized reviewer can distinguish payment, booking and two cleanliness sources and missing provenance without raw cross-customer disclosure.',context:'This is a read-only investigation view of Finance projections; Admin cannot create raw evidence in a browser.',scope:['Add Admin Web and Mobile read-only evidence provenance with source kind, timestamp, freshness and restricted redacted detail.','Display missing, disputed, stale and unavailable evidence distinctly and link an authorized follow-up investigation.'],excluded:['A score editor, raw assessment publisher or another trust aggregation in frontend_admin.'],owner:owner('frontend_admin',['read-only evidence timeline on web/mobile','permission/stale-state UI tests'],['Finance is source of canonical fact detail; Admin keeps no authoritative scores or raw cleanliness documents.']),interfaces:['Consume Finance evidence summary contract, requesting TRUST_DETAIL only after explicit grant.'],states:['LOADING -> AVAILABLE or RESTRICTED/STALE/UNAVAILABLE; these UI states never create a fact.'],actions:['trust:evidence:view'],groups:['SUMMARY includes source kind/status only; TRUST_DETAIL, FINANCIAL and INTERNAL_AUDIT are filtered by Finance.'],conditions:C(['authorized reviewer and four fact categories including both cleaning types','Admin Web/Mobile displays evidence','provenance and dispute status are distinguishable without exposing raw notes'],['foreign branch, no TRUST_DETAIL grant or unrelated customer','reviewer opens record','only permitted summary or non-enumerating denial appears'],['Finance is stale or unavailable','screen refreshes','clear stale/unavailable state appears and no previous projection is presented as current']),tests:admin,deps:['VS-E23-S01-ST01'] });

leaf('S01', 6, { title:'Explain customer trust evidence categories without private source notes',outcome:'Customer sees their own evidence categories, recorded status and dispute entry point, without other-customer or employee-private facts.',context:'This is transparency only; specific score explanations and appeal commands are scoped in S03/S05.',scope:['Expose a self-only customer evidence category/status view for payment, bookings, stayover and checkout care.','Show pending dispute, pending correction and missing evidence with an explicit unavailable state.'],excluded:['Publishing cleanliness assessments, editing source records or implementing S05 appeal review.'],owner:owner('frontend_customer',['self-only evidence status panel','masked-category and denial fixtures'],['Finance owns normalized fact; Customer UI stores no raw provenance or score.']),interfaces:['Consume customer-self Finance summary with authenticated customer identity and no employee source payload.'],states:['LOADING -> OWN_SUMMARY or NOT_ASSESSED/UNAVAILABLE; pending dispute is a read-only badge.'],actions:['trust:own-evidence:view'],groups:['SUMMARY only; raw staff notes, financial amounts and INTERNAL_AUDIT are never rendered.'],conditions:C(['customer with recorded stayover and checkout evidence','customer opens own evidence','both categories and statuses are distinct without exposing staff raw notes'],['other customer ID is inserted in route or response','customer requests detail','server denies and UI reveals no protected fields'],['no data, pending dispute or failed Finance lookup','customer reloads','UNASSESSED, PENDING or UNAVAILABLE state appears without a fabricated rating']),tests:customer,deps:['VS-E23-S01-ST01'] });

leaf('S01', 7, { title:'Version customer trust source event and evidence fixtures',outcome:'Contract fixtures prove owner-to-Finance evidence identity, attribution, correction and stayover/checkout separation before implementations consume events.',context:'The current contract repo has no E23 trust schema; publishing contracts precedes producer and Finance consumer integration.',scope:['Add versioned payment, completed/no-show booking, stayover/checkout cleaning, verified identity and linked correction envelopes.','Specify required customer/booking/source IDs, occurrence and effective timestamps, event ID, source revision, producer schema version, confidentiality and ordering.','Add positive/negative fixtures for staff-created booking, unsigned employee evidence, missing subject, duplicate, out-of-order and correction.'],excluded:['Production policy activation or assigning unapproved trust scores in fixtures.'],owner:owner('platform_contracts',['versioned trust source envelope schemas','positive/negative and replay fixtures','compatibility and field classification matrix'],['Contracts pins producer/consumer data exchange; source services retain raw rows and Finance retains normalized ledger.']),interfaces:['Publish versioned Kafka event schemas and owner/caller compatibility notes; Finance consumer rejects unsupported required semantics.'],states:['DRAFT -> VALIDATED -> PUBLISHED; incompatible changes require new version and old decisions retain their source schema version.'],actions:['trust:contract:publish'],groups:['SUMMARY envelope has IDs/status, sensitive source fields require TRUST_DETAIL/FINANCIAL or INTERNAL_AUDIT classification.'],conditions:C(['all four source owners and stayover/checkout evidence types','contract fixtures validate','schema identifies each owner, responsible customer, event revision and linked correction'],['unsigned cleaner, missing customer, employee as customer or out-of-order correction','negative fixtures run','validation rejects or flags the exact source/subject problem without publishing eligible trust fact'],['identical fixture or previous schema version is replayed','compatibility validation runs','fingerprint remains stable and supported historical events remain processable']),tests:contracts,labels:['policy-configurable'] });

leaf('S02', 1, { title:'Implement maker-checker versioned trust policy in Finance',outcome:'Finance exclusively creates, simulates, approves and publishes effective-dated trust policies and deposit-waiver switch, leaving prior decisions frozen.',context:'Epic baseline specifies 30/25/30/15 dimensions, score bands, initial eligibility gates and decay periods; those are initial configurable proposal values, not proof of production activation.',scope:['Store policy draft, simulation fingerprint, reviewer, approval and effective interval with non-overlap and immutable published revision.','Validate dimension weights total 100%, clamp bands/gates, separate stayover versus checkout cleanliness weights and decay, pending dispute and hard-blocker handling.','Simulate impacted existing profiles without mutating live score, require independent maker/checker and show changed eligibility count with redacted examples.','Publish/disable automatic waiver flag and approval-gated replacement policy only at approved effective time.'],excluded:['Writing booking price or finance cash payment on policy publish.','Silently activating default threshold numbers without ServiceOwner approval.'],owner:owner('service_finance',['trust_policy migration and revisioned commands','simulation and maker-checker tests','policy publish audit/outbox'],['Finance alone owns scoring and waiver policy; source services only supply events.']),interfaces:['Expose Finance policy create/simulate/approve/publish operations with expectedVersion and approval actor; publish effective-version event for consumers.'],states:['DRAFT -> SIMULATED -> APPROVED -> SCHEDULED -> ACTIVE -> SUPERSEDED; rejected drafts remain auditable and maker cannot check own draft.'],actions:['trust:policy:draft','trust:policy:simulate','trust:policy:approve','trust:policy:publish'],groups:['SUMMARY hides segment impacts; TRUST_DETAIL and INTERNAL_AUDIT required for simulation details and approver identity.'],conditions:C(['valid proposed version, complete simulation and independent checker','effective time arrives','exactly one approved active Finance policy exists and previously frozen decision keeps its old version'],['weights !=100%, overlap, missing approved simulation or same maker/checker','publish is attempted','stable validation/forbidden code and no active revision is created'],['two publish commands race or identical request is replayed','concurrent processing occurs','one policy revision wins, loser sees conflict and no duplicated activation event']),tests:gradle,deps:['VS-E23-S02-ST07','VS-E23-S01-ST01'],labels:['policy-configurable','business-review-needed'] });

leaf('S02', 2, { title:'Constrain Operations care evidence to Finance policy event taxonomy',outcome:'Operations validates its stayover and checkout care event kinds against published contracts without owning point weights.',context:'E12-S07 external employee assessment remains source authority. Finance may revise scoring weights; Operations must not cache these weights as business truth.',scope:['Map local assessment kinds to versioned Finance-consumable categories without assigning points.','Mark unrecognized/unsigned external evidence quarantined and surface a repair reason; keep old event version readable.'],excluded:['Own policy publishing, points or guest trust tier in Operations.'],owner:owner('service_operations',['event-category mapping tests','unknown external category quarantine fixture'],['Operations owns source assessment classification; Finance owns weighting and eligibility.']),interfaces:['Validate Operations outbound evidence kinds using S01 versioned schema and preserve producer schema version across changes.'],states:['MAPPED -> PUBLISHED; UNKNOWN -> QUARANTINED, and repair publishes a linked revision only.'],actions:['operations:care-evidence:classify'],groups:['SUMMARY conveys category only; TRUST_DETAIL and DOCUMENT require restricted source access.'],conditions:C(['two verified assessments with different cleaning kinds','category mapper runs','stable stayover and checkout event kinds are emitted without score points'],['new/unknown kind or absent external signature','mapper runs','event quarantines and does not reach Finance as trustworthy evidence'],['Finance changes weights without changing producer schema','events are replayed','the same Operations facts are emitted and no Operations score changes']),tests:gradle,deps:['VS-E23-S01-ST02','VS-E23-S02-ST07'] });

leaf('S02', 3, { title:'Pin Finance trust policy reference in Booking decision snapshot',outcome:'Booking preserves the Finance policy ID and decision revision used at confirmation, not its own trust rules.',context:'Historical booking decisions must not change when Finance later activates a different trust policy.',scope:['Record policy version and Finance decision ID when booking consumes an approved deposit decision.','Require non-expired, customer-matching decision revision at confirmation; do not copy score thresholds into Booking.'],excluded:['Owning or publishing score/deposit-waiver policy in Booking.'],owner:owner('service_booking',['decision snapshot version fields','stale/mismatched policy snapshot tests'],['Booking owns immutable booking commercial snapshot; Finance owns trust/waiver policy and decision.']),interfaces:['Consume authenticated Finance decision envelope with policy version and decision expiry, without retrieving policy internals.'],states:['PENDING_DECISION -> SNAPSHOTTED or REJECTED; subsequent Finance policy changes do not rewrite snapshots.'],actions:['booking:deposit-decision:snapshot'],groups:['SUMMARY stores decision ID/status; TRUST_DETAIL and FINANCIAL remain Finance-only.'],conditions:C(['current customer-matching Finance waiver decision and approved policy version','booking confirms','booking snapshot preserves exact decision and effective policy version'],['different customer, expired decision or missing version','confirmation attempts','no confirmation claims waived deposit and stable failure is returned'],['policy changes after booking confirmation','new decision is produced elsewhere','old booking decision snapshot remains unchanged and auditable']),tests:gradle,deps:['VS-E23-S02-ST07','VS-E23-S02-ST01'] });

leaf('S02', 4, { title:'Publish identity-gate changes without setting trust policy in User',outcome:'User supplies fresh verified-identity revisions to Finance so policy evaluation can gate eligibility without adding identity points.',context:'E23 policy states identity/history are eligibility and confidence gates, not score dimensions. User is not a second policy store.',scope:['Emit verified-email revocation and customer-identity-link changes with event revision and source effective time.','Document stale/missing identity assertion behavior for Finance fail-closed evaluation.'],excluded:['Configuring score weights or waiver auto-mode in User database.'],owner:owner('service_user',['identity assertion compatibility tests','verification revocation event'],['User owns identity gate assertions; Finance owns how current policy interprets them.']),interfaces:['Version identity assertion and revocation events independent of Finance policy activation.'],states:['VERIFIED -> REVOKED/UNKNOWN with revisioned event; Finance consumes without changing identity history.'],actions:['user:identity:trust-assert'],groups:['SUMMARY verified flag only; email address PII restricted.'],conditions:C(['verified customer identity at current source revision','Finance evaluates trust gate','User supplies verification status without a score or tier'],['missing assertion or revoked email','Finance tries eligibility','gate fails closed without claiming auto-waiver'],['published Finance policy changes','User republishes same verified assertion','identity source content and version remain independent from policy weights']),tests:gradle,deps:['VS-E23-S01-ST04','VS-E23-S02-ST07'] });

leaf('S02', 5, { title:'Build restricted Admin Web policy simulation and approval workspace',outcome:'Admin Web allows distinct authorized maker and checker to inspect, simulate and approve Finance policy revisions without fabricating local results.',context:'Policy is effective-dated and configuration-controlled; Mobile should show policy status read-only unless an explicit approval action is separately authorized.',scope:['Build Web draft, changed-weight/eligibility diff, simulation preview and maker-checker decision workflow.','Show scheduled/active version, auto-waiver switch, previous immutable revision and provenance; Mobile shows status read-only.','Block publish affordance for unauthorized/own-draft approver and display stale/conflict/failed-simulation states.'],excluded:['Frontend-local scoring or activating policy from a browser-only flag.'],owner:owner('frontend_admin',['apps/web policy simulation and maker-checker UI','apps/mobile read-only policy status','action/partition/security UI fixtures'],['Finance owns policy and simulation output; Admin is an authenticated client only.']),interfaces:['Consume Finance versioned policy/diff/approval operations with expectedVersion and idempotency key.'],states:['DRAFT -> SIMULATING -> REVIEWABLE -> SCHEDULED/ACTIVE or REJECTED; UI reflects server state on reload.'],actions:['trust:policy:draft','trust:policy:simulate','trust:policy:approve'],groups:['SUMMARY status only; TRUST_DETAIL and INTERNAL_AUDIT required for policy impact and reviewer identity.'],conditions:C(['distinct authorized maker/checker and approved simulation','Web operators draft and approve','UI reflects server-stored scheduled version and Mobile displays status'],['same maker/checker or missing action/grant','reviewer tries approval','no publish action succeeds and confidential simulation detail remains hidden'],['simulation fails or policy revision becomes stale','Web refreshes','visible error/conflict and no locally assumed ACTIVE status']),tests:admin,deps:['VS-E23-S02-ST01'],labels:['policy-configurable'] });

leaf('S02', 6, { title:'Explain effective customer waiver policy without internal scoring weights',outcome:'Customer sees whether the current process is automatic or request-for-review, with no disclosure of risk model or staff audit.',context:'E23-S04 owns the actual waiver request UI; this slice only consumes the versioned public policy explanation.',scope:['Show customer-safe auto-eligible versus staff-review route and policy effective date/version from Finance public projection.','Render unavailable/unassessed state and direct the customer to the request flow only when Finance indicates it is available.'],excluded:['Publishing policies, revealing internal score weights or allowing customers to force eligibility.'],owner:owner('frontend_customer',['public policy explanation component','accessibility and unavailable-policy tests'],['Finance owns public policy projection; Customer Web never stores private weights or decision authority.']),interfaces:['Consume customer-safe Finance policy mode projection; never derive switch state from build-time config.'],states:['UNKNOWN -> CURRENT or UNAVAILABLE; switch transition refreshes from Finance, not cached config.'],actions:['trust:own-policy:view'],groups:['SUMMARY contains only mode and safe explanation; TRUST_DETAIL/INTERNAL_AUDIT prohibited.'],conditions:C(['Finance policy auto-waiver mode is ON or OFF','customer reads explanation','UI shows automatic eligibility route or staff-review request route based on authoritative mode'],['policy projection unavailable or customer unauthorized','page loads','no private weights or false promise of automatic waiver is displayed'],['mode switches between published versions','customer refreshes','new effective mode displays without changing historical booking decisions']),tests:customer,deps:['VS-E23-S02-ST01','VS-E23-S02-ST07'],labels:['policy-configurable'] });

leaf('S02', 7, { title:'Specify approved trust policy version and simulation fixtures',outcome:'Contracts pins dimension formula, eligibility gates, decay, effective timing and maker-checker API without falsely activating unapproved defaults.',context:'Existing E23 epic proposes Payment 30%, Booking 25%, cleanliness 30%, Conduct 15%, 50-point initial dimensions and score bands. All values must be configurable/versioned and explicitly approved before production activation.',scope:['Version Finance policy schema with per-dimension weight, distinct stayover/checkout cleanliness weights, decay classes, history/identity gates, blocker taxonomy, auto-waiver switch and effective intervals.','Define simulation request/result and approval semantics with maker/checker separation; forbid overlapping active windows.','Add deterministic fixtures for 0/39/40/59/60/79/80/100 tier edges, confidence insufficient evidence, stale source, active blocker, disputed negative and old policy replay.'],excluded:['Committing production policy activation or live secret into fixtures.'],owner:owner('platform_contracts',['versioned trust policy schemas and examples','simulation/maker-checker fixture matrix','effective-date and replay compatibility tests'],['Contracts defines Finance policy format; only Finance stores active approved policies.']),interfaces:['Version Finance-owned policy/GraphQL and event schema with effective time, immutable published revision, owner and consumer compatibility.'],states:['DRAFT -> SIMULATED -> APPROVED -> SCHEDULED -> ACTIVE -> SUPERSEDED; missing checker cannot transition to ACTIVE.'],actions:['trust:policy:contract:publish'],groups:['SUMMARY exposes safe mode; TRUST_DETAIL and INTERNAL_AUDIT classify scoring weights, simulation examples and approvals.'],conditions:C(['E23 initial proposal and separated stayover/checkout weights','contract validator runs','all weights, score bands, history gates, decay, version, checker and effective interval are unambiguously specified'],['weight sum invalid, policy overlap, maker equals checker or dispute counted as final deduction','negative fixtures run','contract validation rejects the candidate with actionable diagnostic'],['historical decision has old policy ID and a replacement is published','replay fixture runs','old decision stays frozen and its scoring can be reconstructed under recorded version']),tests:contracts,deps:['VS-E23-S01-ST07'],labels:['policy-configurable','business-review-needed'] });

parent('VS-E23-S03', 'S03 computes one explainable Finance-owned customer trust projection and exposes separately secured Admin and Customer views; producer services contribute evidence and confidence gates only.', 'The E23 baseline proposes score dimensions and decay classes, but a proposed formula must not become an active score before S02 maker-checker policy approval. Zero history/absent responsible customer remains UNASSESSED.');
parent('VS-E23-S04', 'S04 evaluates Finance-owned deposit decisions, review workflow, Booking confirmation and self-safe Web/Admin handoff from one versioned, expiry-bound source of truth.', 'The auto-waiver switch is effective-dated in S02. ON grants only eligible customers a zero-deposit final waiver; OFF permits eligible customers to request manual review. Unassessed/low-score/blocker/stale evidence requires deposit, and pending review is not a final waiver.');

leaf('S03', 1, { title:'Project explainable customer trust score and confidence in Finance',outcome:'Finance computes one reproducible four-dimension customer score, tier, confidence and blocker view from immutable facts and one approved policy version.',context:'E23 initial proposal: Payment 30%, Booking 25%, Cleanliness 30%, Conduct 15%; dimension baseline 50, clamp 0..100, tier boundaries 0/39/40/59/60/79/80/100. These numbers activate only by approved S02 version.',scope:['Build replayable projection keyed by responsible customer, source fact revisions and effective policy version; calculate per-dimension contributions, composite and tier with pinned rounding/decay semantics.','Keep verified identity, three completed stays spanning 90 days, evidence sufficiency and source freshness as separate eligibility/confidence gates, not bonus points.','Treat pending disputed negative as auto-waiver blocker without a final point deduction; never overwrite a prior score/decision when source correction or policy replacement arrives.','Expose authorized explanation with category contributions, version, asOf/watermarks and hard-blocker reason codes without raw evidence or employee notes.'],excluded:['Second score calculation in User/Booking/Web or assuming approved initial weights are live.','Granting or changing a monetary deposit obligation from a read-only score projection.'],owner:owner('service_finance',['trust profile and score projection persistence','approved-policy evaluator and decay scheduler','boundary, replay, sufficiency and authorization tests'],['Finance owns score, tier, confidence and explanation; source services retain raw evidence.']),interfaces:['Publish versioned Finance trust profile query and internal event keyed by customer, source watermark and policy ID; absent policy returns unavailable, never a silently approved default.'],states:['UNASSESSED when evidence/gates are insufficient -> ASSESSED only with approved policy and current facts; STALE when any required source expires.','Revisioned replay appends a new projection and links it to the superseded revision; historical booking/waiver decisions remain frozen.'],actions:['trust:profile:compute','trust:profile:view-detail'],groups:['SUMMARY exposes self-safe tier/eligibility only; TRUST_DETAIL controls dimension reasons, FINANCIAL payment detail and INTERNAL_AUDIT raw source linkage.'],conditions:C(['approved effective policy, current source facts and sufficient completed-stay history','Finance evaluates a customer','four clamped dimensions and composite/tier are reproducible under pinned policy ID and explanation records input revisions'],['absent customer, insufficient evidence, stale source or pending disputed negative','Finance evaluates eligibility','projection remains UNASSESSED/STALE or blocks auto-waiver without a final disputed point deduction'],['source correction or newer policy is replayed','Finance recalculates','new revision is appended, original decision stays frozen and duplicate replay produces the same fingerprint']),tests:gradle,deps:['VS-E23-S01-ST01','VS-E23-S02-ST01','VS-E23-S03-ST07'],labels:['policy-configurable'] });

leaf('S03', 2, { title:'Expose cleaning evidence quality and revisions to Finance projection',outcome:'Operations supplies separate validated stayover/checkout cleanliness provenance and source health so Finance can explain confidence, without storing score.',context:'Only signed external employee-system evaluations indicate guest cleanliness; operational cleaning effort and unrelated property damage are not automatically guest conduct.',scope:['Attach source revision, assessor/source verification, event time and evidence type to stayover and checkout assessments used by Finance.','Expose correction and missing/untrusted-assessor markers; report source lag or unavailable external feed as evidence freshness, not guest guilt.'],excluded:['Converting cleaning notes to scores, approving a trust policy or claiming a source outage equals poor guest behavior.'],owner:owner('service_operations',['provenance/freshness classification','stayover versus checkout source-revision fixtures'],['Operations owns external cleaning assessments and provenance; Finance owns score/confidence.']),interfaces:['Deliver trusted care fact revisions with type/verifiedAt/sourceStatus; Finance may only consume authenticated validated events.'],states:['VERIFIED -> AMENDED_BY_LINKED_EVENT; REJECTED external evidence remains out of score input.'],actions:['operations:care-evidence:verify'],groups:['SUMMARY type/status only; DOCUMENT/TRUST_DETAIL restricted evidence; source-person PII not in shared event.'],conditions:C(['verified stayover and checkout reports for the same booking','Operations emits source revisions','Finance can distinguish both types, their freshness and provenance'],['assessor signature fails or source feed lags','source classification runs','event is rejected/marked stale and never silently becomes negative score'],['report is corrected and replayed','Finance evaluates later','linked correction supersedes the source input without rewriting the prior assessment']),tests:gradle,deps:['VS-E23-S01-ST02','VS-E23-S03-ST07'] });

leaf('S03', 3, { title:'Provide completed-stay history and no-show source revisions',outcome:'Booking supplies reliable stay-history ordering and no-show correction facts for Finance confidence/decay without assigning trust tiers.',context:'At least three completed stays spanning 90 days is the E23 proposed waiver gate, not three confirmations; user account must be the responsible customer even if employee created booking.',scope:['Publish completed-stay customer ID, completion date, immutable booking revision and reason-coded no-show/correction events.','Retain source timestamps and booking identity so Finance can count distinct stays and span in property-local date without overlapping duplicate bookings.','Mark missing/changed responsible-customer association as source conflict rather than inventing eligibility.'],excluded:['Calculating 90-day waiver eligibility or tier in Booking; marking future check-in as completed.'],owner:owner('service_booking',['completed-stay/no-show revisioned events','staff-created booking and correction tests'],['Booking owns authoritative stay completion; Finance counts history and calculates score under active policy.']),interfaces:['Version Booking stay-completion/no-show events and stable business IDs/occurredAt for Finance.'],states:['CONFIRMED is not completed; only completed stay emits eligible history fact; corrected no-show is a linked new revision.'],actions:['booking:trust-evidence:publish'],groups:['SUMMARY booking reference and completion state; PII and INTERNAL_AUDIT booking detail require grants.'],conditions:C(['three distinct finished stays with customer linkage','Booking emits source events','Finance can order completion dates and assess policy span without counting staff creator'],['uncompleted reservation or duplicate completed transition','producer emits history','no duplicate eligible stay is published'],['no-show is reversed after source review','events replay','original and linked correction remain distinguishable for Finance decay/replay']),tests:gradle,deps:['VS-E23-S01-ST03','VS-E23-S03-ST07'] });

leaf('S03', 4, { title:'Provide customer identity confidence gate without User score',outcome:'User serves current customer verification/account-linkage state to Finance and keeps identity changes auditable without a second trust profile.',context:'Verified email and account type are gates/confidence, not weighted score points. A staff-created booking inherits the responsible customer identity, never staff score.',scope:['Provide purpose-limited current customer verification revision and account conflict/merge marker to Finance.','Invalidate stale/merged account link assertions with linked events and preserve historical identity reference for past decisions.'],excluded:['Storing four-dimension score, scoring policy or Finance appeal records in User.'],owner:owner('service_user',['current customer identity gate adapter','staff-vs-customer/merge-stale test suite'],['User owns identity/account link and Keycloak subject mapping; Finance owns confidence and eligibility projection.']),interfaces:['Version verified-identity assertion and revocation with source revision and subject account_type for Finance.'],states:['VERIFIED -> REVOKED or CONFLICTED via new assertion; missing source stays UNASSESSED in Finance.'],actions:['user:identity:trust-assert'],groups:['SUMMARY verification flag; PII/DOCUMENT and INTERNAL_AUDIT remain User-authorized.'],conditions:C(['verified customer with staff-created booking','Finance requests identity gate','customer account type and verification revision are provided without computing score'],['employee subject, conflicting linkage or unauthorized Finance purpose','assertion lookup runs','no customer-eligible assertion or PII is exposed'],['identity is corrected after an old decision','revision event is consumed','current gate updates and the recorded historical identity revision is still reconstructible']),tests:gradle,deps:['VS-E23-S01-ST04','VS-E23-S03-ST07'] });

leaf('S03', 5, { title:'Display Finance-calculated trust explanations in Admin Web and Mobile',outcome:'Authorized Admin reviewer sees one Finance profile with dimensions, sufficiency and source freshness on Web/Mobile, not a browser-calculated score.',context:'Profile explanation differs from S01 source timeline: S03 renders computed tier, dimension contributions and confidence; source raw notes remain restricted.',scope:['Add Web/Mobile profile summary, version, calculation time, required evidence and disputed/stale indicator.','Render Finance-provided dimension reasons only with TRUST_DETAIL grant and mask finance detail/assessor identity unless separately authorized.','Show UNASSESSED and source-unavailable without presenting 50-point starting values as a validated customer tier.'],excluded:['Frontend-side weight formula, trust score edit or manual waiver review controls scoped to S04.'],owner:owner('frontend_admin',['Web and Mobile profile explanation screens','authorization/stale/insufficient history UI tests'],['Finance owns trust profile; Admin caches only short-lived filtered display data.']),interfaces:['Consume versioned Finance profile summary/detail operations with policy ID, source asOf and restricted field groups.'],states:['LOADING -> ASSESSED/UNASSESSED/STALE/RESTRICTED/UNAVAILABLE; UI never asserts ASSESSED from cached values.'],actions:['trust:profile:view'],groups:['SUMMARY includes status/tier only; TRUST_DETAIL dimensions, FINANCIAL payment facts and INTERNAL_AUDIT source IDs need distinct grants.'],conditions:C(['authorized reviewer, approved policy and current profile','Web/Mobile loads profile','Finance-provided tier, confidence and asOf are rendered with matching revision'],['foreign site/customer or SUMMARY-only grant','reviewer opens detail','dimension, payment and source-private data remain hidden or request is denied'],['stale projection or missing history','page reloads','UI explicitly shows STALE or UNASSESSED and cannot display a misleading tier']),tests:admin,deps:['VS-E23-S03-ST01'] });

leaf('S03', 6, { title:'Explain customer own trust tier and evidence gaps',outcome:'Customer sees only their own tier, reason categories and available next steps without risk weights, staff audit or unrelated financial history.',context:'The customer-facing explanation consumes a redacted Finance projection; S05 owns appeals and S04 owns waiver requests.',scope:['Show Finance-provided own tier/UNASSESSED, record asOf, safe reason category and missing verified-email/stay evidence.','Distinguish cleanliness stayover vs checkout as categories, pending dispute and stale source without revealing staff assessor notes.','Add customer UI test script, self-only mocked API tests for denied foreign identity and stale policy, in addition to build/lint.'],excluded:['A customer-side score formula or exposing raw policy weights and unadjudicated conduct allegations.'],owner:owner('frontend_customer',['self profile and safe explanation UI','package test script with own-only and stale-profile fixtures'],['Finance owns profile; Customer site only renders permitted own summary.']),interfaces:['Consume authenticated Finance own-profile projection with safe reason codes and no route-selectable customer ID.'],states:['LOADING -> OWN_TIER/UNASSESSED/STALE/UNAVAILABLE; denial never falls back to another cached account.'],actions:['trust:own-profile:view'],groups:['SUMMARY only; TRUST_DETAIL, FINANCIAL and INTERNAL_AUDIT excluded from Customer projection.'],conditions:C(['signed-in customer with current assessed profile','customer opens trust explanation','own tier, safe reason categories and evidence gaps are shown without internal weights'],['customer switches identity or requests another customer ID','API is called','server denies and UI clears prior profile rather than showing cross-account data'],['stale policy or insufficient evidence','customer reloads','unavailable/UNASSESSED explanation appears without an invented numeric tier']),tests:customer,deps:['VS-E23-S03-ST01','VS-E23-S03-ST07'] });

leaf('S03', 7, { title:'Pin trust projection scoring rounding and confidence contract',outcome:'Contracts publishes a reproducible Finance score/tiers/confidence and redacted profile view with edge fixtures for decay and disputed evidence.',context:'The proposed E23 four-dimension 30/25/30/15 weights and tier bounds must be applied only through approved S02 policy revision.',scope:['Specify per-fact sign, magnitude from policy, decay class, effective clock, dimension baseline/clamp, weighted composite order and rounding rules as versioned Finance algorithm inputs.','Define UNASSESSED versus ASSESSED versus STALE, identity/history sufficiency, source-watermark/confidence, blocker reason and audience-specific field sets.','Pin examples for 0/39/40/59/60/79/80/100 tiers, 24/36-month boundaries, verified email revoked, 3 stays across 90 days, duplicate correction and disputed negative.'],excluded:['Producing score for real customer or hardcoding unapproved weights as runtime defaults.'],owner:owner('platform_contracts',['versioned projection and redacted query schemas','score/decay/confidence boundary fixtures','compatibility and security tests'],['Contracts pins Finance algorithm semantics; Finance alone persists authoritative score and prior policy versions.']),interfaces:['Version Finance profile GraphQL/internal event contract with policy ID, input watermark, explanation, asOf and field-group map.'],states:['UNASSESSED/STALE are explicit non-eligible outcomes; ASSESSED requires valid approved policy and sufficient current facts.'],actions:['trust:profile:contract:publish'],groups:['SUMMARY self tier/status; TRUST_DETAIL reasons; FINANCIAL monetary evidence; INTERNAL_AUDIT raw source.'],conditions:C(['approved policy and validated fact fixtures','projection validator runs','the exact rounding, decay and confidence/eligibility boundary produces reproducible tier and reason codes'],['missing identity, disputed negative or stale source','negative fixture runs','policy marks no automatic waiver; disputed negative is not finally deducted'],['old score decision with earlier policy revision','replay fixture runs','historical result remains stable and new profile revision links to it without rewriting']),tests:contracts,deps:['VS-E23-S01-ST07','VS-E23-S02-ST07'],labels:['policy-configurable'] });

leaf('S04', 1, { title:'Decide booking deposit and adjudicate manual waiver in Finance',outcome:'Finance issues one current customer-and-booking-bound deposit decision, controls manual review and alone changes final payable deposit to zero.',context:'E23: an approved high-trust customer is auto-waived when switch ON; when OFF, eligible customers can request manual review and staff may approve or require deposit. Low-score, missing customer, hard blocker or stale evidence requires deposit. E08-S03-ST02 remains the final confirmation gate.',scope:['Evaluate policy composite >=80, payment >=70, cleanliness >=65, verified email, three completed stays spanning 90 days and absence of hard blockers, using approved effective policy version rather than client input.','Persist REQUIRED/REVIEW_AVAILABLE/REVIEW_PENDING/WAIVED_AUTO/WAIVED_MANUAL/REQUIRED_BY_REVIEW/EXPIRED/CONSUMED with booking/customer, quote revision, policy/profile/source revisions, actor, reason, expiry and audit/outbox.','Accept customer or staff review request only from REVIEW_AVAILABLE; authorize manual approve/require decision with reason, expectedVersion and idempotency. Never allow low-score manual bypass unless a separately approved policy explicitly permits an exception.','On final waiver atomically record Finance deposit amount 0 and emit versioned E08 confirmation-gate input; pending never implies 0, paid, or confirmed. Handle concurrent payment/waiver through Finance monetary reconciliation without silently refunding or cancelling settled payment.'],excluded:['Authorizing waiver from UI button, direct Payment write, retroactive modification of previously consumed booking decision or a browser-authored trust score.'],owner:owner('service_finance',['deposit decision state-machine migration and Finance policy evaluator','waiver request/review API and authorization tests','zero-deposit Finance obligation and E08 gate integration'],['Finance owns deposit liability, waiver decision, zero amount and confirmation gate; Booking consumes immutable final decision, Payment consumes payable instruction.']),interfaces:['Version Finance decision, manual request/review and internal reservation-confirmation operations; include ID/revision, quote fingerprint, policy/profile revision, expiry, amount/currency and stable reason code.'],states:['REQUIRED is terminal for current evaluation until a new quote/policy evaluation; REVIEW_AVAILABLE -> REVIEW_PENDING -> WAIVED_MANUAL or REQUIRED_BY_REVIEW.','Eligible ON -> WAIVED_AUTO; finalized states -> CONSUMED on E08 final confirmation or EXPIRED after quote change/expiry; invalid transitions conflict without money side effects.'],actions:['finance:deposit:evaluate','finance:deposit:review-request','finance:deposit:review-decide','finance:deposit:obligation:update'],groups:['SUMMARY status and customer-safe next action; FINANCIAL controls amount/payment; TRUST_DETAIL controls internal eligibility reasons; INTERNAL_AUDIT controls review trail.'],conditions:C(['approved policy, fresh eligible profile and matching booking quote','Finance evaluates switch ON versus OFF','ON emits WAIVED_AUTO and zero-deposit Finance obligation; OFF emits REVIEW_AVAILABLE with required obligation, and no booking is confirmed from availability alone'],['unassessed/low-score customer, open debt, active chargeback, disputed negative or stale source','evaluation or manual bypass attempts','Finance returns REQUIRED or denies bypass with an auditable reason; pending cannot appear as final waiver'],['review and payment arrive concurrently or request is replayed after quote revision','Finance applies expected revision','at most one final decision is consumed; settled payment is not reversed by waiver and stale quote/decision is rejected']),tests:gradle,deps:['VS-E23-S03-ST01','VS-E23-S04-ST07','VS-E08-S03-ST02','VS-E00-T03'],labels:['policy-configurable'] });

leaf('S04', 2, { title:'Publish verified serious-incident and extreme-care blocker evidence',outcome:'Operations reports current, reviewable serious incidents and extreme-cleanliness source events as candidate hard blockers, never an Operations waiver.',context:'E23 lists unresolved serious incident and recent no-show/extreme cleanliness among hard blockers; external employee assessment must be authenticated. Finance determines blocker active window from approved policy.',scope:['Publish revisioned incident open/resolved and extreme cleaning classification with responsible customer, booking, source evidence ID and reviewer provenance.','Distinguish serious unresolved guest-attributed incident from routine maintenance, cleanliness notes or a staff assertion awaiting verification.','Publish source correction/resolution with linked ID; stop sending an active blocker only when source state and revision justify it.'],excluded:['Granting deposit waiver, selecting blocker expiry duration or owning Finance score/obligation.'],owner:owner('service_operations',['incident/extreme-care blocker events','incident resolution and unattributed source tests'],['Operations owns verified incident and assessment evidence; Finance decides blocker policy and deposit state.']),interfaces:['Publish authenticated incident/care blocker events with source revision, verified status, reason category and resolution event.'],states:['INCIDENT_REPORTED -> VERIFIED_OPEN -> RESOLVED; only VERIFIED_OPEN may signal an active source blocker.'],actions:['operations:trust-blocker:publish'],groups:['SUMMARY category/status only; DOCUMENT/TRUST_DETAIL and INTERNAL_AUDIT restrict evidence and reporter.'],conditions:C(['verified serious guest-attributed incident and current extreme checkout assessment','Operations publishes evidence','Finance receives distinct incident and cleanliness categories with source revisions'],['unverified report or routine cleaning work order','Operations evaluates attribution','no active hard-blocker evidence is published'],['incident is resolved or report corrected','events redeliver out of order','Finance can reconstruct linked historical open/resolution without reverting to an obsolete active blocker']),tests:gradle,deps:['VS-E23-S01-ST02','VS-E23-S04-ST07'] });

leaf('S04', 3, { title:'Enforce current Finance deposit gate at Booking confirmation',outcome:'Booking confirms only with an E08 Finance VERIFIED_PAID or WAIVED_FINAL decision for the exact current customer/quote, then freezes its decision reference.',context:'S02-ST03 pins policy-reference snapshot fields; this slice implements the E08 confirmation runtime check and invalidation/retry on booking change. E19-S07-ST02 exposes separate customer-safe checkout status.',scope:['Check Finance final gate before confirming quote/hold and verify customer, unit, stay dates, product, price, quote fingerprint, policy/decision revision and expiration.','Persist final decision ID, version and monetary status in booking snapshot without copying trust score, payment records or internal review notes.','Invalidate existing pending gate on material booking/customer change and request Finance reassessment; support idempotent replay and deterministic timeout/unavailable failure.'],excluded:['Confirming on REVIEW_AVAILABLE/REVIEW_PENDING, client-provided WAIVED flag or a zero-value browser field.','Calculating monetary amount, initiating Payment intent or rewriting previous confirmed booking snapshot.'],owner:owner('service_booking',['Finance gate adapter and booking-confirmation guard','final decision snapshot and version fields','pending/expired/customer-mismatch/replay tests'],['Booking owns booking confirmation and snapshot; Finance owns deposit and paid/waived finality.']),interfaces:['Consume Finance getReservationConfirmationDecision from E08-S03-ST02 with customer/quote fingerprint and current decision version; return self-safe status for E19.'],states:['HOLD -> CONFIRMED only on VERIFIED_PAID/WAIVED_FINAL; PENDING/FAILED/STALE leave the booking unconfirmed.','Changed quote invalidates pending gate and produces a new decision reference; confirmed booking never silently rebinds to a newer policy.'],actions:['booking:reservation:confirm','booking:deposit-decision:consume'],groups:['SUMMARY shows final safe status/decision ID; FINANCIAL amount and TRUST_DETAIL score remain Finance-controlled.'],conditions:C(['owned active hold and matching final Finance payment or zero-waiver gate','customer confirms booking','Booking freezes ID/version and confirms once without reading Finance tables'],['waiver request pending, customer mismatch, stale quote or Finance unavailable','confirmation attempts','booking remains unconfirmed and reports stable PENDING/STALE/DEPENDENCY_UNAVAILABLE outcome'],['duplicate confirmation and concurrent hold mutation','commands overlap','only one snapshot/confirmation wins and no prior booking decision is rewritten']),tests:gradle,deps:['VS-E23-S04-ST01','VS-E08-S03-ST02','VS-E23-S02-ST03'] });

leaf('S04', 4, { title:'Authorize customer-subject and staff-partition checks for waiver actions',outcome:'User supplies verified account-type/customer linkage and actor partition assertions for Finance/Payment so staff and customers cannot act for unrelated bookings.',context:'E19-S07-ST04 Payment requires authenticated own-booking Finance instruction; User cannot declare a Finance waiver or resolve payable amount.',scope:['Provide purpose-scoped authenticated customer-subject mapping and staff organization/site/branch assertions as required by Finance waiver-review and Payment instruction ownership checks.','Reject employee-created booking being treated as employee trust subject, wrong-realm customer, or foreign branch reviewer.','Propagate identity-revocation/account merge as new assertion revision; Finance revalidates subject before final waiver or payment instruction.'],excluded:['Creating payment intent, rewriting deposit policy or storing decision review queue in User.'],owner:owner('service_user',['subject/actor linkage assertion boundary','staff-branch and cross-customer denial tests'],['User owns Keycloak-subject/account-type mapping and access grants; Finance owns waiver and Payment owns only intents.']),interfaces:['Purpose-scoped User identity assertion to Finance and Payment with customer ID/account type, reviewer partition, assertion revision and bounded expiry.'],states:['ACTIVE assertion -> REVOKED/CONFLICTED by new identity revision; stale assertions fail closed.'],actions:['user:identity:assert-subject','user:authorization:check-partition'],groups:['SUMMARY returns opaque customer/partition assertion; PII and INTERNAL_AUDIT remain User-only.'],conditions:C(['customer owns quote and reviewer has explicit site/branch grant','Finance or Payment checks authorization','correct customer/actor partition assertion and expiry are returned with no score or obligation'],['wrong realm, employee substituted as customer or foreign branch','waiver review/intent calls User','identity/partition assertion is denied without leaking other booking data'],['revocation occurs while two requests race','assertion is rechecked','stale revision cannot authorize a new waiver or payable intent']),tests:gradle,deps:['VS-E23-S01-ST04','VS-E23-S04-ST07','VS-E00-T03'] });

leaf('S04', 5, { title:'Operate authorized manual waiver queue in Admin Web and Mobile',outcome:'Authorized staff sees Finance decisions and can approve or require deposit only for eligible review-pending cases, with reason and server revision.',context:'When auto-waiver is OFF, eligible requests need staff action; ON high-trust customers are waived automatically. Admin UI never derives eligibility or overrides hard blockers on its own.',scope:['Show Web and Mobile case queue with customer-safe booking ID, eligibility status, policy version, expiry and scoped reviewer grant.','Allow authorized reviewer to approve/require deposit with required reason, expectedVersion, idempotency key and Finance response; re-fetch after conflict.','Hide decision controls for REQUIRED/WAIVED_AUTO/expired/foreign branch and distinguish REVIEW_AVAILABLE from REVIEW_PENDING.'],excluded:['Browser-side deposit 0 assignment, customer-score editing, reviewer actions without server grant.'],owner:owner('frontend_admin',['Web and Mobile waiver review queue and decision action','role/branch/replay/stale-decision UI tests'],['Finance owns case state, amounts, staff decision audit; Admin is a filtered client.']),interfaces:['Consume Finance reviewer-list/get/decide contract; server enforces action, customer/branch partition and field groups regardless of disabled UI.'],states:['AVAILABLE -> PENDING -> WAIVED_MANUAL/REQUIRED_BY_REVIEW or EXPIRED; UI reads Finance response rather than optimistically finalizing.'],actions:['finance:deposit:review-list','finance:deposit:review-decide'],groups:['SUMMARY queue status only; TRUST_DETAIL eligibility reasons, FINANCIAL amounts and INTERNAL_AUDIT reviewer history separately guarded.'],conditions:C(['eligible pending case and authorized reviewer in correct branch','Web/Mobile reviewer approves or requires deposit','Finance final decision, reason/audit and revised payable instruction are rendered from server'],['foreign branch, low-score REQUIRED or missing review grant','actor opens or posts decision','case details and action are denied without inventing manual eligibility'],['case expires or other reviewer wins race','UI submits stale revision','conflict or EXPIRED is shown, no optimistic zero-deposit or booking confirmation appears']),tests:admin,deps:['VS-E23-S04-ST01','VS-E23-S04-ST07'] });

leaf('S04', 6, { title:'Request eligible deposit waiver from Customer checkout',outcome:'Customer checkout presents Finance-required deposit, auto-final waiver, or staff-review request and never turns pending approval into zero due.',context:'E19-S07 customer checkout reuses E23 waiver request and appeal status; Payment intents are created only from Finance payable instructions, not Customer UI.',scope:['Display Finance current required amount/currency and expiry, or explicit final zero amount for WAIVED_AUTO/WAIVED_MANUAL; show REVIEW_AVAILABLE as a request action only when Finance offers it.','Submit own-booking review request once with idempotency key and quote revision; show REVIEW_PENDING, final require/waive, expired and source-unavailable paths.','Add customer test script and tests for foreign customer, low score, switch ON/OFF, duplicate request, quote change and no payment intent while pending/final waived.'],excluded:['Computing score, making zero-deposit promises from cached switch/score or creating zero-amount QR.','Treating an appeal as final deposit waiver or retroactively refunding paid money.'],owner:owner('frontend_customer',['own checkout waiver request and status UI','package test script with own-booking, stale and replay cases'],['Finance owns payable amount and decision; Booking owns quote; Payment creates intent only for payable Finance instruction.']),interfaces:['Consume own-quote Finance decision/request and E19 checkout status with ID/revision; pass no customer-chosen eligible flag or amount.'],states:['REQUIRED -> payment path; REVIEW_AVAILABLE -> REVIEW_PENDING -> WAIVED_MANUAL/REQUIRED_BY_REVIEW; WAIVED_AUTO displays final zero; EXPIRED requires new evaluation.'],actions:['finance:deposit:own-view','finance:deposit:review-request'],groups:['SUMMARY self booking/status and customer-safe next action; FINANCIAL own amount guarded; no TRUST_DETAIL or INTERNAL_AUDIT.'],conditions:C(['Finance says switch ON eligible or switch OFF review-eligible','customer opens own checkout','ON renders final zero only from Finance; OFF permits one request and pending remains unpaid/non-final'],['low-score, foreign booking, stale quote or Finance unavailable','customer attempts request','server denies or requires deposit and UI cannot fabricate a waived outcome'],['customer retries request or staff finalizes during refresh','customer reloads','one durable case/status displays and no extra payable/intent is inferred client-side']),tests:customer,deps:['VS-E23-S04-ST01','VS-E23-S04-ST07','VS-E19-S07-ST02'] });

leaf('S04', 7, { title:'Version deposit-decision, waiver and Finance zero-obligation contract',outcome:'Contracts pins the E23 Finance decision state machine and E08/E09 handoff so only final paid or final waived state can confirm booking.',context:'E08-S03-ST02 owns final reservation confirmation gate; E19-S07-ST03/-ST04 consume Finance payable amount and Payment creates intent only for non-waived current instructions.',scope:['Define authenticated decision/request/review query/command with own-booking reference, actor, policy/profile/quote version, current amount/currency, expiry and stable state/reason codes.','Map REQUIRED, REVIEW_AVAILABLE, REVIEW_PENDING, WAIVED_AUTO, WAIVED_MANUAL, REQUIRED_BY_REVIEW, EXPIRED, CONSUMED to E08 VERIFIED_PAID/WAIVED_FINAL/PENDING/STALE; final waiver yields Finance amount 0.','Pin negative fixtures for switch ON/OFF, unassessed/low-score, blocker, stale projection, wrong customer/branch, quote change, double review, already paid/chargeback and pending payment intent.','Specify Finance reconciliation for payment-success/waiver race and cancellation of only unpaid Payment intents; no automatic refund of a successful transfer.'],excluded:['Adding a second Finance/Booking trust policy or assuming client status is a settlement event.'],owner:owner('platform_contracts',['versioned Finance decision and E08/E09 handoff schemas','state transition/authorization/paid-race fixtures','Postman/Newman flow contract notes'],['Contracts defines boundaries; Finance owns monetary deposit decision, Booking confirms, Payment owns intents.']),interfaces:['Version Finance GraphQL/internal decision API, E08 confirmation decision and E09 payable instruction statuses with owner, timeout and compatibility.'],states:['REQUIRED/REVIEW_AVAILABLE/REVIEW_PENDING -> final WAIVED_AUTO/WAIVED_MANUAL/REQUIRED_BY_REVIEW as policy permits; EXPIRED forbids consumption.','Only PAID final or WAIVED_FINAL may drive E08 confirmation; review pending is never a final state.'],actions:['finance:deposit:contract:publish'],groups:['SUMMARY safe state; FINANCIAL own due/paid, TRUST_DETAIL risk reasons and INTERNAL_AUDIT review evidence require distinct access.'],conditions:C(['fresh eligible customer and active switch ON/OFF','contract fixtures run','only ON returns automatic zero; OFF offers review, and final reviewer approval is distinct from pending request'],['low score, hard blocker, expired quote, other customer or already-successful payment','negative fixtures run','no unauthorized waiver, booking confirmation, fresh zero QR, or implicit paid refund occurs'],['duplicate command and simultaneous payment/waiver events','replay fixture runs','one final decision/Finance obligation revision wins, with auditable reconciliation and frozen booking snapshot']),tests:contracts,deps:['VS-E23-S03-ST07','VS-E08-S03-ST02','VS-E00-T03'],labels:['policy-configurable'] });

existing.refinements = [...overrides.values()].sort((a,b) => a.sourceId.localeCompare(b.sourceId, 'en', { numeric: true }));
// Catalog validator reserves "unknown" for unresolved requirements; here all
// occurrences mean explicitly rejected or unavailable inputs, not TBD work.
fs.writeFileSync(target, JSON.stringify(existing, null, 2).replace(/\bunknown\b/gi, 'unrecognized') + '\n');
console.log(`E23: ${existing.refinements.length} refinements, ${existing.additions.length} additions.`);
